const COLLAGEN_ROUTINE_DAYS = Object.fromEntries(Object.entries(days).map(([key, value]) => [key, value]));
let ACTIVE_ROUTINE_ID = localStorage.getItem("activeRoutineId") || "collagen-30";
if (!ROUTINE_CATALOG[ACTIVE_ROUTINE_ID]) ACTIVE_ROUTINE_ID = "collagen-30";

function getActiveRoutineId() { return ACTIVE_ROUTINE_ID; }
function getActiveRoutineConfig() { return ROUTINE_CATALOG[ACTIVE_ROUTINE_ID]; }
function isBackendManagedRoutine() { return Boolean(getActiveRoutineConfig().backend); }
function getRoutineDays(routineId = ACTIVE_ROUTINE_ID) {
  return routineId === "collagen-30" ? COLLAGEN_ROUTINE_DAYS : PRODUCT_ROUTINE_DAYS[routineId].days;
}
function applyActiveRoutineContent() {
  Object.keys(days).forEach(key => delete days[key]);
  Object.assign(days, getRoutineDays());
}
applyActiveRoutineContent();

function setActiveRoutineV92(routineId) {
  if (!ROUTINE_CATALOG[routineId]) return;
  ACTIVE_ROUTINE_ID = routineId;
  localStorage.setItem("activeRoutineId", routineId);
  applyActiveRoutineContent();
  TOTAL_PROGRAM_DAYS = getActiveRoutineConfig().totalDays;
  CURRENT_ROUTINE_ID = routineId;
  CURRENT_ROUTINE_TITLE = getActiveRoutineConfig().title;
  const state = getRoutineState();
  selectedDay = Math.max(1, Math.min(Number(state.currentDay || 1), TOTAL_PROGRAM_DAYS));
  localStorage.setItem(`selectedDay:${routineId}`, String(selectedDay));
  document.querySelectorAll(".home-routine-selector button").forEach(button =>
    button.classList.toggle("is-active", button.dataset.routineId === routineId));
  const heading = document.querySelector(".home-routine-card-active .home-routine-heading h2");
  if (heading) heading.textContent = getActiveRoutineConfig().title;
  const nativeTitle = document.querySelector(".daily-native-title strong");
  if (nativeTitle) nativeTitle.textContent = getActiveRoutineConfig().title;
  closeNativeDayView();
  renderSelectedDayHeader();
  chat.innerHTML = "";
  renderStructuredDayDetail();
  renderDays();
  renderFavorites();
}

function setupMultiRoutineV92() {
  const section = document.querySelector(".home-routines-section .home-section-heading");
  if (!section || document.querySelector(".home-routine-selector")) return;
  const selector = document.createElement("div");
  selector.className = "home-routine-selector";
  Object.values(ROUTINE_CATALOG).forEach(config => {
    const button = document.createElement("button");
    button.type = "button";
    button.dataset.routineId = config.id;
    button.textContent = config.title;
    button.classList.toggle("is-active", config.id === ACTIVE_ROUTINE_ID);
    button.onclick = () => setActiveRoutineV92(config.id);
    selector.appendChild(button);
  });
  section.insertAdjacentElement("afterend", selector);
  const originalSelectDay = selectDay;
  selectDay = function(day, showImmediately = false) {
    if (!isBackendManagedRoutine()) {
      const state = getRoutineState();
      state.currentDay = Number(day);
      saveRoutineState(state);
    }
    return originalSelectDay(day, showImmediately);
  };
  setActiveRoutineV92(ACTIVE_ROUTINE_ID);
}

